import Link from "next/link";
export default function ForgotPassword(){return <main><div className="container"><div className="formCard" style={{maxWidth:520}}><span className="eyebrow">Vendor portal</span><h1>Reset your password.</h1><p className="meta">Enter your account email and we’ll send a secure reset link.</p><form action="/api/auth/reset" method="post"><div className="field"><label>Email</label><input name="email" type="email" required/></div><button className="btn primary" style={{width:"100%",marginTop:18}}>Send Reset Link</button></form><p className="meta" style={{marginTop:18}}><Link href="/vendor/login">Back to sign in</Link></p></div></div></main>}
